 35 FPClassTest llvm::inverse_fabs(FPClassTest Mask) {
 36   FPClassTest NewMask = Mask & fcNan;
 37   if (Mask & fcPosZero)
 38     NewMask |= fcZero;
 39   if (Mask & fcPosSubnormal)
 40     NewMask |= fcSubnormal;
 41   if (Mask & fcPosNormal)
 42     NewMask |= fcNormal;
 43   if (Mask & fcPosInf)
 44     NewMask |= fcInf;
 45   return NewMask;
