 48 FPClassTest llvm::unknown_sign(FPClassTest Mask) {
 49   FPClassTest NewMask = Mask & fcNan;
 50   if (Mask & fcZero)
 51     NewMask |= fcZero;
 52   if (Mask & fcSubnormal)
 53     NewMask |= fcSubnormal;
 54   if (Mask & fcNormal)
 55     NewMask |= fcNormal;
 56   if (Mask & fcInf)
 57     NewMask |= fcInf;
 58   return NewMask;
 59 }
